SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, a.discharge_location, a.deathtime, AVG(a.los) AS average_los, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY a.los) AS p75_los, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY a.los) AS p90_los, COUNT(CASE WHEN a.los <= 7 THEN 1 END) * 100.0 / NULLIF(COUNT(a.los), 0) AS percentage_of_los_less_than_or_equal_to_7_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.subject_id = 93 AND p.gender = 'M' AND p.anchor_age BETWEEN 88 AND 98 AND a.admission_type = 'postoperative proxy' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, a.discharge_location, a.deathtime ORDER BY average_los NULLS LAST, p75_los NULLS LAST, p90_los NULLS LAST, percentage_of_los_less_than_or_equal_to_7_days NULLS LAST;